#!/usr/bin/env bash
# recipes/crate-windows-x86-64-msvc--0-33-0/build.sh -- stage the windows_x86_64_msvc 0.33.0 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/windows_x86_64_msvc-0.33.0"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"ff1e4aa646495048ec7f3ffddc411e1d829c026a2ec62b39da15c1055e406eaa"}\n' > "${dest}/.cargo-checksum.json"
